(6872299, 1035054, 30982, '<td valign="top">Love the flare of her dress - she seems to be in her own little world, quite happy to be there, too.</td>', 'Love the flare of her dress - she seems to be in her own little world, quite happy to be there, too.', '2012-10-01 02:03:49.000000', NULL, 1),
(6872300, 1035274, 17850, '<td valign="top">Excellent mood and image-processing, bravo!</td>', 'Excellent mood and image-processing, bravo!', '2012-10-01 02:03:51.000000', NULL, 1),
(6872304, 1033635, 30982, '<td valign="top">The glow of the color is lovely!  Excellent detail throughout though I suspect the DPC limitations have created a sense of oversharpness.  The glow is just incredible, though!  A calendar-worthy shot, to be sure.</td>', 'The glow of the color is lovely!  Excellent detail throughout though I suspect the DPC limitations have created a sense of oversharpness.  The glow is just incredible, though!  A calendar-worthy shot, to be sure.', '2012-10-01 02:05:26.000000', NULL, 1),
(6872306, 1032507, 30982, '<td valign="top">A sunsprite!  Hard to catch them in their native element.</td>', 'A sunsprite!  Hard to catch them in their native element.', '2012-10-01 02:06:02.000000', NULL, 1),
(6872308, 1033713, 30982, '<td valign="top">He''s so little!  An amazing tableau.</td>', 'He''s so little!  An amazing tableau.', '2012-10-01 02:06:39.000000', NULL, 1),
(6872310, 1035038, 30982, '<td valign="top">Dang, looks cold!  I like the faded sense to this, as though time has gone by.</td>', 'Dang, looks cold!  I like the faded sense to this, as though time has gone by.', '2012-10-01 02:07:27.000000', NULL, 1),
(6872316, 1035425, 30982, '<td valign="top">What a great glare!  Almost wish we had the horse''s eye, too, to see if he''s glaring back...</td>', 'What a great glare!  Almost wish we had the horse''s eye, too, to see if he''s glaring back...', '2012-10-01 02:11:04.000000', NULL, 1),
