INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6873230, 1035601, 112828, '<td valign="top">I love the color combo, curious if it''s natural.  The framing really lets this image down, but the colors are awesome.</td>', 'I love the color combo, curious if it''s natural.  The framing really lets this image down, but the colors are awesome.', '2012-10-02 00:10:30.000000', NULL, 1),
(6873231, 1035527, 112828, '<td valign="top">Image is low contrast, and the sky is completely gray. (as in unnaturally gray)</td>', 'Image is low contrast, and the sky is completely gray. (as in unnaturally gray)', '2012-10-02 00:11:15.000000', NULL, 1),
(6873232, 1034653, 112828, '<td valign="top">Death by tonemapping.</td>', 'Death by tonemapping.', '2012-10-02 00:12:23.000000', NULL, 1),
(6873233, 1033635, 112828, '<td valign="top">Really nice, but over sharpened.</td>', 'Really nice, but over sharpened.', '2012-10-02 00:12:42.000000', NULL, 1),
(6873234, 1035788, 112828, '<td valign="top">Image looks muddy.  Tonemapping can be good, but you need to make certain that you still have blacks and whites in the image.  Everything here is just gray.</td>', 'Image looks muddy.  Tonemapping can be good, but you need to make certain that you still have blacks and whites in the image.  Everything here is just gray.', '2012-10-02 00:13:40.000000', NULL, 1),
(6873236, 1035398, 112828, '<td valign="top">Death by overprocessing/filtering.</td>', 'Death by overprocessing/filtering.', '2012-10-02 00:15:55.000000', NULL, 1),
(6873237, 1034603, 112828, '<td valign="top">Blurry/soft..</td>', 'Blurry/soft..', '2012-10-02 00:16:24.000000', NULL, 1),
(6873238, 1034661, 112828, '<td valign="top">Just a wee bit too much Topaz Clean...</td>', 'Just a wee bit too much Topaz Clean...', '2012-10-02 00:20:14.000000', NULL, 1),
(6873240, 1035428, 112828, '<td valign="top">I love the goat, but there''s a bit too much tonemapping here, it leaves the image feeling muddy.</td>', 'I love the goat, but there''s a bit too much tonemapping here, it leaves the image feeling muddy.', '2012-10-02 00:22:30.000000', NULL, 1),
(6873242, 1035520, 112828, '<td valign="top">Another muddy tonemapped image?  Either my monitor broke tonight, or this is becoming a worrying trend.<br/> <br/>Your whites are all too dark, grab that levels tool and bring those whites out!</td>', 'Another muddy tonemapped image?  Either my monitor broke tonight, or this is becoming a worrying trend. Your whites are all too dark, grab that levels tool and bring those whites out!', '2012-10-02 00:27:05.000000', NULL, 1),
