(6877576, 1035577, 60173, '<td valign="top">You''ve gone too smooth for my taste. It does remind me of a style of art that I can''t put my finger on right now. The style that <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=74588" rel="nofollow" target="_blank">cutout</a> does here on this site. Like an abstract cubism, but not quite. <br/> <br/>I Googled "abstract cubism" and found this image that, while completely different, feels similar.<br/> <br/><a href="//tinyurl.com/9o9erbn" rel="nofollow" target="_blank">//tinyurl.com/9o9erbn</a></td>', 'You''ve gone too smooth for my taste. It does remind me of a style of art that I can''t put my finger on right now. The style that  cutout does here on this site. Like an abstract cubism, but not quite.  I Googled "abstract cubism" and found this image that, while completely different, feels similar. //tinyurl.com/9o9erbn', '2012-10-07 12:25:56.000000', NULL, 1),
(6877578, 1032372, 60173, '<td valign="top">Holy momma! She must have gone straight from the shoot to the hospital.<br/> <br/>As for the photo, I think I would have pulled her away from the wall some more if possible. The shadow there on the bottom right is pretty harsh.</td>', 'Holy momma! She must have gone straight from the shoot to the hospital. As for the photo, I think I would have pulled her away from the wall some more if possible. The shadow there on the bottom right is pretty harsh.', '2012-10-07 12:28:51.000000', NULL, 1),
(6877582, 1035104, 60173, '<td valign="top">That kid is going to kill that baby with that dolphin, and dad appears to be thinking about letting him/her. Oh, and yea, I suppose that lady coming for the photographer is pretty alarming too.</td>', 'That kid is going to kill that baby with that dolphin, and dad appears to be thinking about letting him/her. Oh, and yea, I suppose that lady coming for the photographer is pretty alarming too.', '2012-10-07 12:30:57.000000', NULL, 1),
(6877584, 1035601, 60173, '<td valign="top">I think this could use a tiny touch more contrast, but overall it''s a great photo. I''m curious what the purple is in the background. It compliments the colors of the cat very nicely. Oh, and nice lighting on the face.</td>', 'I think this could use a tiny touch more contrast, but overall it''s a great photo. I''m curious what the purple is in the background. It compliments the colors of the cat very nicely. Oh, and nice lighting on the face.', '2012-10-07 12:32:35.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6877586, 1035050, 60173, '<td valign="top">My first thought was, "Ooo, pretty rainbow" followed by, "Sneakerwave!" I really like how the blues are featured here with the white highlights.</td>', 'My first thought was, "Ooo, pretty rainbow" followed by, "Sneakerwave!" I really like how the blues are featured here with the white highlights.', '2012-10-07 12:34:09.000000', NULL, 1),
(6877592, 1034969, 114225, '<td valign="top">That light is breathtaking.</td>', 'That light is breathtaking.', '2012-10-07 12:43:34.000000', NULL, 1),
(6877593, 1035672, 60173, '<td valign="top">The lighting and balance of tones in this image are fantastic. It''s almost deceiving how natural it looks while still looking so perfectly lit in all the right places. At first glance the image appears pretty flat, but I think that''s only because it''s mashed between a multitude of other strongly saturated DPC photos. There''s very subtle reds and greens that come out the more you stare. The DOF is great too.</td>', 'The lighting and balance of tones in this image are fantastic. It''s almost deceiving how natural it looks while still looking so perfectly lit in all the right places. At first glance the image appears pretty flat, but I think that''s only because it''s mashed between a multitude of other strongly saturated DPC photos. There''s very subtle reds and greens that come out the more you stare. The DOF is great too.', '2012-10-07 12:44:04.000000', NULL, 1),
(6877594, 1035737, 60173, '<td valign="top">A touch too smooth I think. She appears to be outside, so in my opinion shouldn''t have the smooth studio look. I would give her some of her natural texture back.</td>', 'A touch too smooth I think. She appears to be outside, so in my opinion shouldn''t have the smooth studio look. I would give her some of her natural texture back.', '2012-10-07 12:45:59.000000', NULL, 1),
(6877596, 1035670, 114225, '<td valign="top">That''s some scary intensity in those eyes.</td>', 'That''s some scary intensity in those eyes.', '2012-10-07 12:46:55.000000', NULL, 1),
(6877597, 1035646, 60173, '<td valign="top">Wonderfully clear reflection, but I''m sure by now others have told you that it''s way too saturated.</td>', 'Wonderfully clear reflection, but I''m sure by now others have told you that it''s way too saturated.', '2012-10-07 12:47:17.000000', NULL, 1),
(6877598, 1035330, 114225, '<td valign="top">Well done.</td>', 'Well done.', '2012-10-07 12:48:01.000000', NULL, 1),
(6877600, 1035518, 114225, '<td valign="top">Wow, very cool.</td>', 'Wow, very cool.', '2012-10-07 12:48:56.000000', NULL, 1),
(6877602, 1035282, 60173, '<td valign="top">That''s funny, I looked very quickly at this and went back to a previous photo to give it another look. As I flipped away I said to myself, "I see a dog." Now I come back and see your title, shazam, dog. I think I see a St. Bernard.</td>', 'That''s funny, I looked very quickly at this and went back to a previous photo to give it another look. As I flipped away I said to myself, "I see a dog." Now I come back and see your title, shazam, dog. I think I see a St. Bernard.', '2012-10-07 12:50:41.000000', NULL, 1),
(6877603, 1035537, 114225, '<td valign="top">What an interesting place.</td>', 'What an interesting place.', '2012-10-07 12:51:11.000000', NULL, 1),
(6877604, 1035426, 114225, '<td valign="top">Very nice. I like how the light highlights the subjects.</td>', 'Very nice. I like how the light highlights the subjects.', '2012-10-07 12:51:53.000000', NULL, 1),
(6877606, 1034960, 114225, '<td valign="top">There isn''t really anything outstanding here, but something just draws me in to this photo.</td>', 'There isn''t really anything outstanding here, but something just draws me in to this photo.', '2012-10-07 12:52:39.000000', NULL, 1),
(6877607, 1035427, 60173, '<td valign="top">That''s probably the best shot of that hole I''ve seen here at DPC. I would be curious what the shot would have looked like 20 minutes earlier. I do love the orange there on the left water, but the foreground does seem a little dark.</td>', 'That''s probably the best shot of that hole I''ve seen here at DPC. I would be curious what the shot would have looked like 20 minutes earlier. I do love the orange there on the left water, but the foreground does seem a little dark.', '2012-10-07 12:52:58.000000', NULL, 1),
(6877609, 1035670, 60173, '<td valign="top">Yea, that''s the guy I want to be ordering a hotdog from, not. Maybe a pretzel though, I like pretzels.<br/> <br/>Nice job recognizing the light and smokey mystery surrounding him.</td>', 'Yea, that''s the guy I want to be ordering a hotdog from, not. Maybe a pretzel though, I like pretzels. Nice job recognizing the light and smokey mystery surrounding him.', '2012-10-07 12:54:34.000000', NULL, 1),
(6877611, 1035633, 60173, '<td valign="top">Nice pan! I love how solid your horizontal lines are too. This really is a pro shot.</td>', 'Nice pan! I love how solid your horizontal lines are too. This really is a pro shot.', '2012-10-07 12:57:29.000000', NULL, 1),
(6877613, 1035548, 60173, '<td valign="top">I so wish the quality of this were better. The bottom especially looks like it lost a lot of detail due to processing. My assumption is that it was lost in the attempt to remove ISO grain? <br/> <br/>What an incredible scene though, two amazing Earthly wonders in one capture. I wish I could have seen it.</td>', 'I so wish the quality of this were better. The bottom especially looks like it lost a lot of detail due to processing. My assumption is that it was lost in the attempt to remove ISO grain?  What an incredible scene though, two amazing Earthly wonders in one capture. I wish I could have seen it.', '2012-10-07 13:01:28.000000', NULL, 1),
(6877615, 1035525, 67152, '<td valign="top">beautifully rendered image - a classic landscape</td>', 'beautifully rendered image - a classic landscape', '2012-10-07 13:07:11.000000', NULL, 1),
(6877617, 1035496, 67152, '<td valign="top">mysterious</td>', 'mysterious', '2012-10-07 13:12:40.000000', NULL, 1),
(6877618, 1035766, 67152, '<td valign="top">a wonderful face - a bit hard on the contrast levels to blow out some hair, but it is a very good portrait of this noble creature</td>', 'a wonderful face - a bit hard on the contrast levels to blow out some hair, but it is a very good portrait of this noble creature', '2012-10-07 13:13:21.000000', NULL, 1),
(6877626, 1035707, 30049, '<td valign="top">:-)  This makes me smile 1) for the gonads to enter it, and 2) for the simple pleasing qualities of the capture.<br/> <br/>One nit I have is the sensor dust spots mostly evident in lower middle.</td>', ':-)  This makes me smile 1) for the gonads to enter it, and 2) for the simple pleasing qualities of the capture. One nit I have is the sensor dust spots mostly evident in lower middle.', '2012-10-07 13:49:59.000000', NULL, 1),
(6877627, 1035706, 30049, '<td valign="top">Senior portrait?  Overall I like the lighting and background choice.  However, two things that take away IMO are the fallen diagonal branches upper left, and the one bottom right (that mirrors the angle of her arm).  Minus those, this would be elevated substantially more score-wise.</td>', 'Senior portrait?  Overall I like the lighting and background choice.  However, two things that take away IMO are the fallen diagonal branches upper left, and the one bottom right (that mirrors the angle of her arm).  Minus those, this would be elevated substantially more score-wise.', '2012-10-07 13:52:29.000000', NULL, 1),
