(6878059, 1035827, 67697, '<td valign="top">Great capture.  Love how the muscles are defined by the light.</td>', 'Great capture.  Love how the muscles are defined by the light.', '2012-10-08 00:52:09.000000', NULL, 1),
(6878062, 1035404, 54645, '<td valign="top">Gorgeous light and texture. Well done.<br/> <br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=963227" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/50000-54999/54645/120/Copyrighted_Image_Reuse_Prohibited_963227.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/50000-54999/54645/120/Copyrighted_Image_Reuse_Prohibited_963227.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/50000-54999/54645/120/Copyrighted_Image_Reuse_Prohibited_963227.jpg"/></a></td>', 'Gorgeous light and texture. Well done. ', '2012-10-08 00:52:18.000000', NULL, 1),
(6878064, 1035673, 67697, '<td valign="top">Not sure why, but I really do find this to be a compelling photo.  This is quite an engaging portrait.</td>', 'Not sure why, but I really do find this to be a compelling photo.  This is quite an engaging portrait.', '2012-10-08 00:52:46.000000', NULL, 1),
(6878068, 1035808, 54645, '<td valign="top">Ha!<br/> <br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=963227" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/50000-54999/54645/120/Copyrighted_Image_Reuse_Prohibited_963227.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/50000-54999/54645/120/Copyrighted_Image_Reuse_Prohibited_963227.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/50000-54999/54645/120/Copyrighted_Image_Reuse_Prohibited_963227.jpg"/></a></td>', 'Ha! ', '2012-10-08 00:53:28.000000', NULL, 1),
(6878070, 1035346, 67697, '<td valign="top">I like how the definition of the sky kind of makes your eyes loop around to the man and dog, and then back out to the water.</td>', 'I like how the definition of the sky kind of makes your eyes loop around to the man and dog, and then back out to the water.', '2012-10-08 00:53:33.000000', NULL, 1),
(6878074, 1033547, 67697, '<td valign="top">This is fun.  What a great idea for painting with light.</td>', 'This is fun.  What a great idea for painting with light.', '2012-10-08 00:54:12.000000', NULL, 1),
(6878075, 1034547, 54645, '<td valign="top">Powerful</td>', 'Powerful', '2012-10-08 00:54:27.000000', NULL, 1),
(6878079, 1035817, 67697, '<td valign="top">So cute.  She looks quite proud of her drawing.  Is that a bird in green then?</td>', 'So cute.  She looks quite proud of her drawing.  Is that a bird in green then?', '2012-10-08 00:54:50.000000', NULL, 1),
(6878080, 1035808, 67697, '<td valign="top">Perfect hair for this gorgeous silhouette.</td>', 'Perfect hair for this gorgeous silhouette.', '2012-10-08 00:55:16.000000', NULL, 1),
